class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
        vector<vector<int>> adj(n);
        for (int i = 0; i < n - 1; ++i) {
            adj[i].push_back(i + 1);
        }
        vector<int> ans;
        for (const auto& q : queries) {
            adj[q[0]].push_back(q[1]);
            vector<int> dist(n, -1);
            dist[0] = 0;
            queue<int> que;
            que.push(0);
            while (!que.empty()) {
                int curr = que.front();
                que.pop();
                if (curr == n - 1) break;
                for (int nxt : adj[curr]) {
                    if (dist[nxt] == -1) {
                        dist[nxt] = dist[curr] + 1;
                        que.push(nxt);
                    }
                }
            }
            ans.push_back(dist[n - 1]);
        }
        return ans;
    }
};

class Solution {
    public int[] shortestDistanceAfterQueries(int n, int[][] queries) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; ++i) adj.add(new ArrayList<>());
        for (int i = 0; i < n - 1; ++i) {
            adj.get(i).add(i + 1);
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            adj.get(queries[i][0]).add(queries[i][1]);
            int[] dist = new int[n];
            Arrays.fill(dist, -1);
            dist[0] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.add(0);
            while (!q.isEmpty()) {
                int curr = q.poll();
                if (curr == n - 1) break;
                for (int nxt : adj.get(curr)) {
                    if (dist[nxt] == -1) {
                        dist[nxt] = dist[curr] + 1;
                        q.add(nxt);
                    }
                }
            }
            ans[i] = dist[n - 1];
        }
        return ans;
    }
}

var shortestDistanceAfterQueries = function(n, queries) {
    const adj = Array.from({ length: n }, () => []);
    for (let i = 0; i < n - 1; i++) {
        adj[i].push(i + 1);
    }
    const ans = [];
    for (const [u, v] of queries) {
        adj[u].push(v);
        const dist = new Array(n).fill(-1);
        dist[0] = 0;
        const q = [0];
        let head = 0;
        while (head < q.length) {
            const curr = q[head++];
            if (curr === n - 1) break;
            for (const nxt of adj[curr]) {
                if (dist[nxt] === -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.push(nxt);
                }
            }
        }
        ans.push(dist[n - 1]);
    }
    return ans;
};
